import{_ as e,c as n,o as i,a0 as a}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Inleiding tot het mentale spel - Deelnemershandleiding","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/nl/participant-guide.md","filePath":"public/downloads/nl/participant-guide.md"}');const r=e({name:"public/downloads/nl/participant-guide.md"},[["render",function(e,t,r,l,o,s){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="inleiding-tot-het-mentale-spel-deelnemershandleiding" tabindex="-1">Inleiding tot het mentale spel - Deelnemershandleiding <a class="header-anchor" href="#inleiding-tot-het-mentale-spel-deelnemershandleiding" aria-label="Permalink to &quot;Inleiding tot het mentale spel - Deelnemershandleiding&quot;">​</a></h1><p><strong>Pétanque Academie</strong><em>Ontwikkeling van topspelers</em></p><hr><h2 id="welkom" tabindex="-1">Welkom <a class="header-anchor" href="#welkom" aria-label="Permalink to &quot;Welkom&quot;">​</a></h2><p>Vandaag leer je praktische mentale technieken om je pétanque-prestaties te verbeteren.</p><h3 id="wat-je-zult-leren" tabindex="-1">Wat je zult leren <a class="header-anchor" href="#wat-je-zult-leren" aria-label="Permalink to &quot;Wat je zult leren&quot;">​</a></h3><ul><li>Waarom mentale training belangrijk is voor topspelers</li><li>Het verschil tussen &quot;technische modus&quot; en &quot;flowmodus&quot;</li><li>Hoe herken je je innerlijke criticus en hoe ga je ermee om?</li><li>Eenvoudige technieken voor drukbeheersing</li><li>Een basisroutine vóór de opname</li></ul><hr><h2 id="de-zone-flowtoestand" tabindex="-1">De zone-/flowtoestand <a class="header-anchor" href="#de-zone-flowtoestand" aria-label="Permalink to &quot;De zone-/flowtoestand&quot;">​</a></h2><h3 id="wat-is-flow" tabindex="-1">Wat is flow? <a class="header-anchor" href="#wat-is-flow" aria-label="Permalink to &quot;Wat is flow?&quot;">​</a></h3><p>Flow is die magische toestand waarin:</p><ul><li>Alles voelt moeiteloos aan.</li><li>De tijd lijkt langzamer te gaan.</li><li>Je denkt niet na, je speelt gewoon.</li><li>Je techniek wordt perfect uitgevoerd.</li></ul><h3 id="twee-denkwijzen" tabindex="-1">Twee denkwijzen <a class="header-anchor" href="#twee-denkwijzen" aria-label="Permalink to &quot;Twee denkwijzen&quot;">​</a></h3><p><strong>Planningsmodus (Analytisch)</strong></p><ul><li>Het terrein analyseren</li><li>Je strategie kiezen</li><li>De keuze voor het shot bepalen</li><li>Risicobeoordeling</li></ul><p><strong>Uitvoeringsmodus (Flow)</strong></p><ul><li>Vertrouwen in je lichaam</li><li>Niet nadenken over de techniek</li><li>Focus op het huidige moment</li><li>Automatische uitvoering</li></ul><h3 id="de-schakelaar" tabindex="-1">De schakelaar <a class="header-anchor" href="#de-schakelaar" aria-label="Permalink to &quot;De schakelaar&quot;">​</a></h3><p>De belangrijkste vaardigheid: <strong>omschakelen van planningsmodus naar uitvoeringsmodus</strong></p><p><strong>Vóór de opname:</strong> Analyseren, plannen, beslissen <strong>Tijdens de opname:</strong> Vertrouwen, flow, uitvoeren</p><hr><h2 id="de-innerlijke-criticus-versus-de-innerlijke-coach" tabindex="-1">De innerlijke criticus versus de innerlijke coach <a class="header-anchor" href="#de-innerlijke-criticus-versus-de-innerlijke-coach" aria-label="Permalink to &quot;De innerlijke criticus versus de innerlijke coach&quot;">​</a></h2><h3 id="je-innerlijke-criticus-zegt" tabindex="-1">Je innerlijke criticus zegt: <a class="header-anchor" href="#je-innerlijke-criticus-zegt" aria-label="Permalink to &quot;Je innerlijke criticus zegt:&quot;">​</a></h3><ul><li>&quot;Dat was vreselijk!&quot;</li><li>&quot;Je maakt altijd fouten onder druk.&quot;</li><li>&quot;Iedereen kijkt toe hoe je faalt&quot;</li><li>&quot;Je bent niet goed genoeg&quot;</li></ul><h3 id="je-innerlijke-coach-zegt" tabindex="-1">Je innerlijke coach zegt: <a class="header-anchor" href="#je-innerlijke-coach-zegt" aria-label="Permalink to &quot;Je innerlijke coach zegt:&quot;">​</a></h3><ul><li>&quot;Wat kan ik hiervan leren?&quot;</li><li>&quot;Volgende kans, een nieuwe start&quot;</li><li>&quot;Ik heb deze foto al eerder gemaakt.&quot;</li><li>&quot;Vertrouw op het proces&quot;</li></ul><h3 id="herkaderingsoefening" tabindex="-1">Herkaderingsoefening <a class="header-anchor" href="#herkaderingsoefening" aria-label="Permalink to &quot;Herkaderingsoefening&quot;">​</a></h3><p>Wanneer je je innerlijke criticus herkent:</p><ol><li><strong>Pauze</strong> - Herken het kritische denkproces.</li><li><strong>Herformuleren</strong> - Wat zou jouw coach zeggen?</li><li><strong>Reset</strong> - Neem 3 ademhalingen</li><li><strong>Opnieuw scherpstellen</strong> - Volgende opname</li></ol><hr><h2 id="praktische-hulpmiddelen" tabindex="-1">Praktische hulpmiddelen <a class="header-anchor" href="#praktische-hulpmiddelen" aria-label="Permalink to &quot;Praktische hulpmiddelen&quot;">​</a></h2><h3 id="_3-ademhaling-reset" tabindex="-1">3-ademhaling reset <a class="header-anchor" href="#_3-ademhaling-reset" aria-label="Permalink to &quot;3-ademhaling reset&quot;">​</a></h3><p>Gebruik dit na fouten of wanneer je druk voelt:</p><ol><li><strong>Ademhaling 1:</strong> Merk de spanning op (waar voel je die?)</li><li><strong>Ademhaling 2:</strong> Laat de spanning los (laat het gaan)</li><li><strong>Ademhaling 3:</strong> Richt je aandacht weer op het nu (deze foto, dit moment)</li></ol><h3 id="voorbereidingsroutine" tabindex="-1">Voorbereidingsroutine <a class="header-anchor" href="#voorbereidingsroutine" aria-label="Permalink to &quot;Voorbereidingsroutine&quot;">​</a></h3><p>Creëer consistentie met een eenvoudige routine:</p><ol><li><strong>Visualiseer</strong> - Zie het schot voor je geestesoog.</li><li><strong>Adem in</strong> - één keer diep ademhalen</li><li><strong>Anker</strong> - Raak je boule aan, voel het gewicht</li><li><strong>Uitvoeren</strong> - Vertrouwen en gooien</li></ol><h3 id="foutcorrectieprotocol" tabindex="-1">Foutcorrectieprotocol <a class="header-anchor" href="#foutcorrectieprotocol" aria-label="Permalink to &quot;Foutcorrectieprotocol&quot;">​</a></h3><p>Na een mislukte poging:</p><ol><li><strong>Erkennen</strong> - &quot;Dat ging niet zoals gepland&quot;</li><li><strong>Loslaten</strong> - Fysieke reset (afschudden, lopen)</li><li><strong>Heroriënteer je</strong> - &quot;De volgende foto is een nieuwe kans&quot;</li><li><strong>Uitvoeren</strong> - Vertrouw op je routine</li></ol><hr><h2 id="jouw-actieplan" tabindex="-1">Jouw actieplan <a class="header-anchor" href="#jouw-actieplan" aria-label="Permalink to &quot;Jouw actieplan&quot;">​</a></h2><h3 id="deze-week" tabindex="-1">Deze week <a class="header-anchor" href="#deze-week" aria-label="Permalink to &quot;Deze week&quot;">​</a></h3><p>Kies ÉÉN techniek om te oefenen:</p><ul><li>[ ] 3-ademhalingen reset na elke fout</li><li>[ ] Voorbereidingsroutine bij elke worp</li><li>[ ] Herformuleer één gedachte van de innerlijke criticus per sessie</li><li>[ ] Oefen het overschakelen van de planningsmodus naar de uitvoeringsmodus</li></ul><h3 id="volg-je-voortgang" tabindex="-1">Volg je voortgang <a class="header-anchor" href="#volg-je-voortgang" aria-label="Permalink to &quot;Volg je voortgang&quot;">​</a></h3><p>Kennisgeving:</p><ul><li>Wanneer ervaar je het meest een flow-ervaring?</li><li>Wat triggert jouw innerlijke criticus?</li><li>Welke techniek helpt jou het meest?</li><li>Hoe verandert je prestatie?</li></ul><hr><h2 id="bronnen-en-vervolgstappen" tabindex="-1">Bronnen en vervolgstappen <a class="header-anchor" href="#bronnen-en-vervolgstappen" aria-label="Permalink to &quot;Bronnen en vervolgstappen&quot;">​</a></h2><h3 id="verder-leren" tabindex="-1">Verder leren <a class="header-anchor" href="#verder-leren" aria-label="Permalink to &quot;Verder leren&quot;">​</a></h3><ul><li><strong>De Zone</strong> - Een diepgaande verkenning van flowtoestanden</li><li><strong>Mentale kracht</strong> - Geavanceerd omgaan met druk</li><li><strong>Doelsjabloon</strong> - Structureer uw ontwikkeling</li><li><strong>Dagboeksjabloon</strong> - Houd je voortgang bij</li></ul><h3 id="oefen-dagelijks" tabindex="-1">Oefen dagelijks <a class="header-anchor" href="#oefen-dagelijks" aria-label="Permalink to &quot;Oefen dagelijks&quot;">​</a></h3><ul><li>5 minuten bewuste ademhaling</li><li>Visualiseer succesvolle schoten</li><li>Oefen je voorbereiding op de foto.</li><li>Herformuleer negatieve gedachten</li></ul><hr><h2 id="belangrijkste-conclusies" tabindex="-1">Belangrijkste conclusies <a class="header-anchor" href="#belangrijkste-conclusies" aria-label="Permalink to &quot;Belangrijkste conclusies&quot;">​</a></h2><ol><li><strong>De flow-status is toegankelijk</strong> - Je kunt leren om er consistenter in terecht te komen.</li><li><strong>Je innerlijke stem is belangrijk</strong> - Coach jezelf, wees niet zelfkritisch.</li><li><strong>Eenvoudige hulpmiddelen werken</strong> - 3 ademhalingsoefeningen, een routine, een reset.</li><li><strong>Oefening is de sleutel</strong> - Mentale vaardigheden vereisen training, net als technische vaardigheden.</li></ol><hr><p><strong>Onthoud dit:</strong> Mentale training gaat niet over positief denken. Het gaat over praktische technieken die je helpen om onder druk optimaal te presteren.</p><hr><p><em>Bezoek carreau.app voor meer informatie</em><em>Pétanque Academie - Ontwikkeling van elitespelers</em></p>',61)])])}]]);export{t as __pageData,r as default};
